.section .text.boot
.balign 4

// ==========================================================================
// Kernel Entry Point (Executed at 0x40080000)
// ==========================================================================
.global _start
_start:
    // 1. Enable SIMD / Floating-Point access in EL1 and EL0 (CPACR_EL1.FPEN = 0b11)
    // Prevents FP register traps generated by GCC -O2 memcpy/memset optimizations
    mrs     x1, cpacr_el1
    orr     x1, x1, #(3 << 20)
    msr     cpacr_el1, x1
    isb

    // 2. Install Exception Vector Table into VBAR_EL1
    adrp    x1, vector_table
    add     x1, x1, :lo12:vector_table
    msr     vbar_el1, x1
    isb

    // 3. Setup initial kernel stack pointer
    adrp    x1, boot_stack_top
    add     x1, x1, :lo12:boot_stack_top
    mov     sp, x1

    // 4. Pass DTB physical address (received in x0 from bootloader) to kmain
    bl      kmain

    // Fallback low-power WFE loop if kmain ever returns
1:  wfe
    b       1b

// ==========================================================================
// AArch64 Exception Vector Table
// ==========================================================================
.section .text.vectors
.balign 2048
.global vector_table
vector_table:
    // --- Current EL with SP0 ---
    .balign 128
    mov x9, #0; b trap_invalid_common
    .balign 128
    mov x9, #1; b trap_invalid_common
    .balign 128
    mov x9, #2; b trap_invalid_common
    .balign 128
    mov x9, #3; b trap_invalid_common

    // --- Current EL with SPx ---
    .balign 128
    b trap_sync_common
    .balign 128
    mov x9, #5; b trap_invalid_common
    .balign 128
    mov x9, #6; b trap_invalid_common
    .balign 128
    mov x9, #7; b trap_invalid_common

    // --- Lower EL using AArch64 ---
    .balign 128
    b trap_sync_common
    .balign 128
    mov x9, #9; b trap_invalid_common
    .balign 128
    mov x9, #10; b trap_invalid_common
    .balign 128
    mov x9, #11; b trap_invalid_common

    // --- Lower EL using AArch32 ---
    .balign 128
    mov x9, #12; b trap_invalid_common
    .balign 128
    mov x9, #13; b trap_invalid_common
    .balign 128
    mov x9, #14; b trap_invalid_common
    .balign 128
    mov x9, #15; b trap_invalid_common

// ==========================================================================
// Exception Trap Vector Common Dispatchers
// ==========================================================================
.text
.balign 4

trap_sync_common:
    // Allocate CpuContext (272 bytes = 17 * 16 bytes) on stack
    sub     sp, sp, #272
    stp     x0,  x1,  [sp, #0]
    stp     x2,  x3,  [sp, #16]
    stp     x4,  x5,  [sp, #32]
    stp     x6,  x7,  [sp, #48]
    stp     x8,  x9,  [sp, #64]
    stp     x10, x11, [sp, #80]
    stp     x12, x13, [sp, #96]
    stp     x14, x15, [sp, #112]
    stp     x16, x17, [sp, #128]
    stp     x18, x19, [sp, #144]
    stp     x20, x21, [sp, #160]
    stp     x22, x23, [sp, #176]
    stp     x24, x25, [sp, #192]
    stp     x26, x27, [sp, #208]
    stp     x28, x29, [sp, #224]
    str     x30,      [sp, #240]

    mrs     x0, sp_el0
    str     x0, [sp, #248]
    mrs     x1, elr_el1
    str     x1, [sp, #256]
    mrs     x2, spsr_el1
    str     x2, [sp, #264]

    // Route to C++ synchronous exception handler
    mov     x0, sp              // arg1: HAL::CpuContext* ctx
    mrs     x1, esr_el1         // arg2: uint64_t esr
    mrs     x2, far_el1         // arg3: uint64_t far
    bl      aarch64_handle_sync_exception

    // Restore registers
    ldr     x0, [sp, #248]
    msr     sp_el0, x0
    ldr     x1, [sp, #256]
    msr     elr_el1, x1
    ldr     x2, [sp, #264]
    msr     spsr_el1, x2

    ldp     x0,  x1,  [sp, #0]
    ldp     x2,  x3,  [sp, #16]
    ldp     x4,  x5,  [sp, #32]
    ldp     x6,  x7,  [sp, #48]
    ldp     x8,  x9,  [sp, #64]
    ldp     x10, x11, [sp, #80]
    ldp     x12, x13, [sp, #96]
    ldp     x14, x15, [sp, #112]
    ldp     x16, x17, [sp, #128]
    ldp     x18, x19, [sp, #144]
    ldp     x20, x21, [sp, #160]
    ldp     x22, x23, [sp, #176]
    ldp     x24, x25, [sp, #192]
    ldp     x26, x27, [sp, #208]
    ldp     x28, x29, [sp, #224]
    ldr     x30,      [sp, #240]
    add     sp, sp, #272
    eret

trap_invalid_common:
    sub     sp, sp, #272
    stp     x0,  x1,  [sp, #0]
    stp     x2,  x3,  [sp, #16]
    stp     x4,  x5,  [sp, #32]
    stp     x6,  x7,  [sp, #48]
    stp     x8,  x9,  [sp, #64]
    stp     x10, x11, [sp, #80]
    stp     x12, x13, [sp, #96]
    stp     x14, x15, [sp, #112]
    stp     x16, x17, [sp, #128]
    stp     x18, x19, [sp, #144]
    stp     x20, x21, [sp, #160]
    stp     x22, x23, [sp, #176]
    stp     x24, x25, [sp, #192]
    stp     x26, x27, [sp, #208]
    stp     x28, x29, [sp, #224]
    str     x30,      [sp, #240]

    mrs     x0, sp_el0
    str     x0, [sp, #248]
    mrs     x1, elr_el1
    str     x1, [sp, #256]
    mrs     x2, spsr_el1
    str     x2, [sp, #264]

    mov     x0, sp              // arg1: HAL::CpuContext* ctx
    mov     x1, x9              // arg2: uint64_t type
    bl      aarch64_handle_invalid_exception

    ldr     x0, [sp, #248]
    msr     sp_el0, x0
    ldr     x1, [sp, #256]
    msr     elr_el1, x1
    ldr     x2, [sp, #264]
    msr     spsr_el1, x2

    ldp     x0,  x1,  [sp, #0]
    ldp     x2,  x3,  [sp, #16]
    ldp     x4,  x5,  [sp, #32]
    ldp     x6,  x7,  [sp, #48]
    ldp     x8,  x9,  [sp, #64]
    ldp     x10, x11, [sp, #80]
    ldp     x12, x13, [sp, #96]
    ldp     x14, x15, [sp, #112]
    ldp     x16, x17, [sp, #128]
    ldp     x18, x19, [sp, #144]
    ldp     x20, x21, [sp, #160]
    ldp     x22, x23, [sp, #176]
    ldp     x24, x25, [sp, #192]
    ldp     x26, x27, [sp, #208]
    ldp     x28, x29, [sp, #224]
    ldr     x30,      [sp, #240]
    add     sp, sp, #272
    eret

// ==========================================================================
// EL0 Context Transition Procedures
// ==========================================================================

.global enter_user_mode
enter_user_mode:
    adrp    x2, kernel_ctx
    add     x2, x2, :lo12:kernel_ctx
    stp     x19, x20, [x2, #0]
    stp     x21, x22, [x2, #16]
    stp     x23, x24, [x2, #32]
    stp     x25, x26, [x2, #48]
    stp     x27, x28, [x2, #64]
    stp     x29, x30, [x2, #80]
    mov     x3, sp
    str     x3,       [x2, #96]

    msr     sp_el0, x1
    msr     elr_el1, x0
    mov     x2, #0x0            // EL0t mode
    msr     spsr_el1, x2

    mov     x0, #0
    mov     x1, #0
    isb
    eret

.global enter_user_context
enter_user_context:
    adrp    x2, kernel_ctx
    add     x2, x2, :lo12:kernel_ctx

    stp     x19, x20, [x2, #0]
    stp     x21, x22, [x2, #16]
    stp     x23, x24, [x2, #32]
    stp     x25, x26, [x2, #48]
    stp     x27, x28, [x2, #64]
    stp     x29, x30, [x2, #80]
    mov     x3, sp
    str     x3,       [x2, #96]

    ldr     x1, [x0, #248]
    msr     sp_el0, x1
    ldr     x1, [x0, #256]
    msr     elr_el1, x1
    ldr     x1, [x0, #264]
    msr     spsr_el1, x1

    ldr     x2, [x0, #0]         // x0 (argc)
    ldr     x3, [x0, #8]         // x1 (argv)

    mov     x4, #0
    mov     x5, #0
    mov     x6, #0
    mov     x7, #0
    mov     x8, #0
    mov     x9, #0
    mov     x10, #0
    mov     x11, #0
    mov     x12, #0
    mov     x13, #0
    mov     x14, #0
    mov     x15, #0
    mov     x16, #0
    mov     x17, #0
    mov     x18, #0
    mov     x19, #0
    mov     x20, #0
    mov     x21, #0
    mov     x22, #0
    mov     x23, #0
    mov     x24, #0
    mov     x25, #0
    mov     x26, #0
    mov     x27, #0
    mov     x28, #0
    mov     x29, #0
    mov     x30, #0

    mov     x0, x2
    mov     x1, x3
    mov     x2, #0
    mov     x3, #0

    isb
    eret

.global return_to_kernel
return_to_kernel:
    adrp    x2, kernel_ctx
    add     x2, x2, :lo12:kernel_ctx
    ldp     x19, x20, [x2, #0]
    ldp     x21, x22, [x2, #16]
    ldp     x23, x24, [x2, #32]
    ldp     x25, x26, [x2, #48]
    ldp     x27, x28, [x2, #64]
    ldp     x29, x30, [x2, #80]
    ldr     x3,       [x2, #96]
    mov     sp, x3
    ret

// ==========================================================================
// Test Helpers
// ==========================================================================

.global user_space_code
user_space_code:
    mov     x8, #93             // SYS_EXIT
    mov     x0, #0
    svc     #0

.global trigger_svc_test
trigger_svc_test:
    mov     x8, #93             // SYS_EXIT
    mov     x0, #0
    svc     #0

.global el0_sysreg_test_entry
el0_sysreg_test_entry:
    mrs     x0, sctlr_el1
    mov     x8, #93
    svc     #0

// ==========================================================================
// BSS Storage
// ==========================================================================

.section .bss
.balign 16

.global kernel_ctx
kernel_ctx:
    .skip 104

.balign 16
boot_stack_bottom:
    .skip 16384
boot_stack_top: